  let W, H, puntos = [];
  function medir() {
    W = cv.width = innerWidth;
    H = cv.height = innerHeight;
  }
  addEventListener('resize', medir);
  medir();
  for (let k = 0; k < 70; k++) {
    puntos.push({
      x: Math.random() * W, y: Math.random() * H,
      vx: (Math.random() - .5) * .15, vy: (Math.random() - .5) * .15,
      r: Math.random() * 1.4 + .4
    });
  }
  function dibujar() {
    ctx.clearRect(0, 0, W, H);
    for (const p of puntos) {
      p.x += p.vx; p.y += p.vy;
      if (p.x < 0) p.x = W; if (p.x > W) p.x = 0;
      if (p.y < 0) p.y = H; if (p.y > H) p.y = 0;
    }
    ctx.strokeStyle = 'rgba(217,166,107,0.08)';
    for (let a = 0; a < puntos.length; a++) {
      for (let b = a + 1; b < puntos.length; b++) {
        const dx = puntos[a].x - puntos[b].x, dy = puntos[a].y - puntos[b].y;
        if (dx*dx + dy*dy < 130*130) {
          ctx.beginPath();
          ctx.moveTo(puntos[a].x, puntos[a].y);
          ctx.lineTo(puntos[b].x, puntos[b].y);
          ctx.stroke();
        }
      }
    }
    ctx.fillStyle = 'rgba(232,228,218,0.6)';
    for (const p of puntos) {
      ctx.beginPath();
      ctx.arc(p.x, p.y, p.r, 0, Math.PI * 2);
      ctx.fill();
    }
    requestAnimationFrame(dibujar);
  }
