<script>
(function () {
  const canvas = document.getElementById('fondo');
  const ctx = canvas.getContext('2d');
  const reducir = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  let ancho = 0, alto = 0, puntos = [];
  const raton = { x: -9999, y: -9999 };

  function ajustar() {
    const dpr = window.devicePixelRatio || 1;
    ancho = window.innerWidth;
    alto = window.innerHeight;
    canvas.width = ancho * dpr;
    canvas.height = alto * dpr;
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    const n = Math.min(110, Math.floor((ancho * alto) / 13000));
    puntos = [];
    for (let i = 0; i < n; i++) {
      puntos.push({
        x: Math.random() * ancho,
        y: Math.random() * alto,
        vx: (Math.random() - 0.5) * 0.3,
        vy: (Math.random() - 0.5) * 0.3,
        r: 0.8 + Math.random() * 1.6
      });
    }
  }

  function dibujar() {
    ctx.clearRect(0, 0, ancho, alto);
    const distMax = 140;

    for (const p of puntos) {
      p.x += p.vx;
      p.y += p.vy;
      if (p.x < -10) p.x = ancho + 10;
      if (p.x > ancho + 10) p.x = -10;
      if (p.y < -10) p.y = alto + 10;
      if (p.y > alto + 10) p.y = -10;
    }

    for (let i = 0; i < puntos.length; i++) {
      const a = puntos[i];
      for (let j = i + 1; j < puntos.length; j++) {
        const b = puntos[j];
        const dx = a.x - b.x, dy = a.y - b.y;
        const d = Math.sqrt(dx * dx + dy * dy);
        if (d < distMax) {
          ctx.strokeStyle = 'rgba(181, 86, 47, ' + (0.22 * (1 - d / distMax)) + ')';
          ctx.lineWidth = 0.7;
          ctx.beginPath();
          ctx.moveTo(a.x, a.y);
          ctx.lineTo(b.x, b.y);
          ctx.stroke();
        }
      }
      const dr = Math.hypot(a.x - raton.x, a.y - raton.y);
      if (dr < 180) {
        ctx.strokeStyle = 'rgba(43, 42, 39, ' + (0.25 * (1 - dr / 180)) + ')';
        ctx.lineWidth = 0.6;
        ctx.beginPath();
        ctx.moveTo(a.x, a.y);
        ctx.lineTo(raton.x, raton.y);
        ctx.stroke();
      }
    }

    ctx.fillStyle = 'rgba(43, 42, 39, 0.55)';
    for (const p of puntos) {
      ctx.beginPath();
      ctx.arc(p.x, p.y, p.r, 0, Math.PI * 2);
      ctx.fill();
    }

    if (!reducir) requestAnimationFrame(dibujar);
  }

  window.addEventListener('pointermove', (e) => {
    raton.x = e.clientX;
    raton.y = e.clientY;
  });
  window.addEventListener('pointerleave', () => {
    raton.x = -9999;
    raton.y = -9999;
  });
  window.addEventListener('resize', () => {
    ajustar();
    if (reducir) dibujar();
  });

  ajustar();
  dibujar();
})();
</script>

