  }
  window.addEventListener("resize", medir);
  medir();

  var puntas = [];
  function sembrar(px, py) {
    var n = 2 + Math.floor(Math.random() * 3);
    for (var i = 0; i < n; i++) {
      puntas.push({
        x: px, y: py,
        a: -Math.PI / 2 + (Math.random() - 0.5) * 1.6,
