  }
  function angulo(x,y){
    return Math.sin(x*0.0042 + p1) * Math.cos(y*0.0051 + p2) * Math.PI * 2
         + Math.sin((x+y)*0.0021 + p3) * 2;
  }
  function nueva(x,y,vida){
    return {
      x:x, y:y, vida:vida,
      c: Math.random() < 0.18 ? 'rgba(164,69,44,0.13)' : 'rgba(42,38,34,0.09)',
