    ctx.clearRect(0,0,W,H);
    fase();
    parts = [];
    var n = Math.round(Math.min(700, W*H/2600));
    for(var k=0;k<n;k++) parts.push(nueva(Math.random()*W, Math.random()*H, 500 + Math.random()*400));
