  function paso(){
    var vivas = 0;
    for(var k=0;k<parts.length;k++){
      var q = parts[k];
      if(q.vida <= 0) continue;
      var a = angulo(q.x,q.y);
      var nx = q.x + Math.cos(a)*1.6;
      var ny = q.y + Math.sin(a)*1.6;
      ctx.strokeStyle = q.c;
      ctx.lineWidth = q.w;
      ctx.beginPath(); ctx.moveTo(q.x,q.y); ctx.lineTo(nx,ny); ctx.stroke();
