    for(var r=0;r<2;r++) v = paso();
    if(v > 0 && !quieto){ requestAnimationFrame(cuadro); } else { corriendo = false; }
  }
  function arrancar(){
    if(quieto){ return; }
    if(!corriendo){ corriendo = true; requestAnimationFrame(cuadro); }
  }

