    for(var k=0;k<90;k++){
      var r = Math.random()*26, th = Math.random()*Math.PI*2;
      parts.push(nueva(e.clientX + Math.cos(th)*r, e.clientY + Math.sin(th)*r, 300 + Math.random()*300));
