  function hex2rgb(h) {
    h = h.replace('#', '');
    return [parseInt(h.substr(0, 2), 16), parseInt(h.substr(2, 2), 16), parseInt(h.substr(4, 2), 16)];
  }
  function mezcla(c1, c2, k) {
    var a = hex2rgb(c1), b = hex2rgb(c2), out = [];
    for (var i = 0; i < 3; i++) out.push(Math.round(a[i] + (b[i] - a[i]) * k));
    return 'rgb(' + out.join(',') + ')';
  }

  var paradas = [
    { t: 0,    a: '#05070f', b: '#0a1020', c: '#161e33' },
    { t: 4.5,  a: '#05070f', b: '#0a1020', c: '#161e33' },
