    { t: 19.5, a: '#0b0a1a', b: '#2a2038', c: '#b8633f' },
    { t: 21.5, a: '#05070f', b: '#0a1020', c: '#161e33' },
    { t: 24,   a: '#05070f', b: '#0a1020', c: '#161e33' }
  ];

  function paleta(t) {
    for (var i = 0; i < paradas.length - 1; i++) {
      var p0 = paradas[i], p1 = paradas[i + 1];
      if (t >= p0.t && t <= p1.t) {
        var k = (t - p0.t) / ((p1.t - p0.t) || 1);
        return {
          a: mezcla(p0.a, p1.a, k),
          b: mezcla(p0.b, p1.b, k),
          c: mezcla(p0.c, p1.c, k)
        };
      }
    }
    return { a: '#05070f', b: '#0a1020', c: '#161e33' };
  }

  function nocheFactor(t) {
    if (t <= 5 || t >= 21) return 1;
    if (t < 7)  return (7 - t) / 2;
    if (t > 19) return (t - 19) / 2;
    return 0;
