(function(){
  var cv  = document.getElementById('polvo');
  var ctx = cv.getContext('2d');
  var reduce = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  var dpr = Math.min(window.devicePixelRatio || 1, 2);
  var W = 0, H = 0, motas = [];

  function medir(){
    W = window.innerWidth;
    H = window.innerHeight;
    cv.width  = Math.floor(W * dpr);
    cv.height = Math.floor(H * dpr);
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);

    var n = Math.max(24, Math.min(150, Math.round(W * H / 11000)));
    motas = [];
    for (var i = 0; i < n; i++){
      motas.push({
        x: Math.random() * W,
        y: Math.random() * H,
        r: Math.random() * 1.3 + 0.35,
        vx: (Math.random() - 0.5) * 0.09,
        vy: -(Math.random() * 0.11 + 0.015),
        a: Math.random() * 0.42 + 0.10,
        f: Math.random() * Math.PI * 2,
        fs: Math.random() * 0.012 + 0.003
      });
    }
    dibujar();
  }

  function dibujar(){
    ctx.clearRect(0, 0, W, H);
    for (var i = 0; i < motas.length; i++){
      var m = motas[i];
      if (!reduce){
        m.x += m.vx;
        m.y += m.vy;
        m.f += m.fs;
        if (m.y < -12){ m.y = H + 12; m.x = Math.random() * W; }
        if (m.x < -12) m.x = W + 12;
        if (m.x > W + 12) m.x = -12;
      }
      var alfa = m.a * (0.55 + 0.45 * Math.sin(m.f));
      ctx.beginPath();
      ctx.arc(m.x, m.y, m.r, 0, 6.283185);
      ctx.fillStyle = 'rgba(233,228,218,' + alfa.toFixed(3) + ')';
      ctx.fill();
    }
  }

  function bucle(){
    if (reduce) return;
    dibujar();
    requestAnimationFrame(bucle);
  }

  window.addEventListener('resize', medir, { passive: true });
  medir();
  bucle();

  var hora = document.getElementById('hora');
  function tic(){
    var d = new Date();
    var hh = String(d.getHours()).padStart(2, '0');
    var mm = String(d.getMinutes()).padStart(2, '0');
    hora.textContent = 'acá son las ' + hh + ':' + mm;
  }
  tic();
  setInterval(tic, 1000);
})();
</script>

