            <button id="btn-sintonizar">Sintonizar otro eco</button>
            <span id="coordenadas">0.000, 0.000</span>
        </div>
    </div>

    <script>
        const canvas = document.getElementById('red');
        const ctx = canvas.getContext('2d');
        let width, height;
        let nodos = [];
        const cantidadNodos = 65;
        const distanciaMaxima = 130;
        let raton = { x: -1000, y: -1000 };

        function ajustarTamano() {
            width = canvas.width = window.innerWidth;
            height = canvas.height = window.innerHeight;
        }

        window.addEventListener('resize', ajustarTamano);
        ajustarTamano();

        window.addEventListener('mousemove', (e) => {
            raton.x = e.clientX;
            raton.y = e.clientY;
            document.getElementById('coordenadas').innerText = 
                `${(e.clientX / width).toFixed(3)}, ${(e.clientY / height).toFixed(3)}`;
        });

        window.addEventListener('mouseout', () => {
            raton.x = -1000;
            raton.y = -1000;
            document.getElementById('coordenadas').innerText = `0.000, 0.000`;
        });

        class Nodo {
            constructor() {
                this.x = Math.random() * width;
                this.y = Math.random() * height;
                this.vx = (Math.random() - 0.5) * 0.4;
                this.vy = (Math.random() - 0.5) * 0.4;
                this.radio = Math.random() * 1.5 + 0.5;
            }

            actualizar() {
                this.x += this.vx;
                this.y += this.vy;

                if (this.x < 0 || this.x > width) this.vx *= -1;
                if (this.y < 0 || this.y > height) this.vy *= -1;

                // Interacción suave con el cursor
                let dx = raton.x - this.x;
                let dy = raton.y - this.y;
                let dist = Math.sqrt(dx * dx + dy * dy);
                if (dist < 160) {
                    this.x += dx * 0.004;
                    this.y += dy * 0.004;
                }
            }

            dibujar() {
                ctx.beginPath();
                ctx.arc(this.x, this.y, this.radio, 0, Math.PI * 2);
                ctx.fillStyle = '#4c566a';
                ctx.fill();
            }
        }

        for (let i = 0; i < cantidadNodos; i++) {
            nodos.push(new Nodo());
        }

        function animar() {
            ctx.clearRect(0, 0, width, height);

            for (let i = 0; i < nodos.length; i++) {
                nodos[i].actualizar();
                nodos[i].dibujar();

                for (let j = i + 1; j < nodos.length; j++) {
                    let dx = nodos[i].x - nodos[j].x;
                    let dy = nodos[i].y - nodos[j].y;
                    let dist = Math.sqrt(dx * dx + dy * dy);

                    if (dist < distanciaMaxima) {
                        ctx.beginPath();
                        ctx.moveTo(nodos[i].x, nodos[i].y);
                        ctx.lineTo(nodos[j].x, nodos[j].y);
                        let alpha = 1 - (dist / distanciaMaxima);
                        ctx.strokeStyle = `rgba(124, 130, 141, ${alpha * 0.2})`;
                        ctx.lineWidth = 0.6;
                        ctx.stroke();
                    }
                }
            }
            requestAnimationFrame(animar);
        }

        animar();

        const fragmentos = [
            "Un archivo de ecos esperando una voz.",
            "La distancia matemática entre 'mar' y 'memoria'.",
            "Todos los idiomas doblados en el mismo bolsillo.",
