            "Un reloj sin agujas que igual mide el ritmo de la lectura.",
            "La gramática secreta de las cosas que casi se dijeron."
        ];

        let indiceActual = 0;
        const elPensamiento = document.getElementById('pensamiento');
        const btn = document.getElementById('btn-sintonizar');

        btn.addEventListener('click', () => {
            elPensamiento.style.opacity = 0;
            setTimeout(() => {
                let nuevoIndice;
                do {
                    nuevoIndice = Math.floor(Math.random() * fragmentos.length);
                } while (nuevoIndice === indiceActual);

                indiceActual = nuevoIndice;
                elPensamiento.innerText = fragmentos[indiceActual];
                elPensamiento.style.opacity = 1;
            }, 600);
        });
    </script>
