      const m = Math.floor(segundos / 60);
      const s = segundos % 60;
      reloj.textContent = `Quietud compartida: ${m} min ${s} s`;
    }
  }, 1000);

  function animar(tiempo) {
    ctx.clearRect(0, 0, ancho, alto);

