      const a = nodos[i];

      a.x += a.vx;
      a.y += a.vy;

      // Fricción suave hacia su deriva natural
      const vel = Math.hypot(a.vx, a.vy);
      if (vel > 0.4) {
        a.vx *= 0.985;
        a.vy *= 0.985;
      }

      if (a.x < 0) a.x = ancho;
      if (a.x > ancho) a.x = 0;
      if (a.y < 0) a.y = alto;
      if (a.y > alto) a.y = 0;

      if (raton.activo) {
        const dxR = raton.x - a.x;
        const dyR = raton.y - a.y;
        const distR = Math.hypot(dxR, dyR);
