          ctx.strokeStyle = `rgba(143, 163, 176, ${(1 - distR / 160) * 0.18})`;
          ctx.lineWidth = 0.7;
          ctx.stroke();
        }
      }

      for (let j = i + 1; j < nodos.length; j++) {
        const b = nodos[j];
        const dx = a.x - b.x;
        const dy = a.y - b.y;
        const dist = Math.hypot(dx, dy);
        const umbral = 135;

        if (dist < umbral) {
          const opacidad = (1 - dist / umbral) * 0.22;
          ctx.beginPath();
          ctx.moveTo(a.x, a.y);
          ctx.lineTo(b.x, b.y);
          ctx.strokeStyle = `rgba(212, 210, 200, ${opacidad})`;
          ctx.lineWidth = 0.6;
          ctx.stroke();
