        <span class="pulso" aria-hidden="true"></span>
        <span>tocá cualquier espacio libre para dejar una onda</span>
      </span>
      <span id="contador-ondas">0 trazos en esta visita</span>
    </footer>
  </div>

  <script>
    (function () {
      const opciones = [
        ["encargo", "urgencia", "prisa", "ruido"],
        ["margen ancho", "cuarto claro", "papel abierto", "silencio tibio"],
        ["descansan", "esperan", "ensayan", "derivan"],
        ["respuesta", "mapa", "memoria", "conversación"],
        ["trazo", "eco", "círculo", "destello"]
      ];

      const estado = [0, 0, 0, 0, 0];
      const botonesSlot = Array.from(document.querySelectorAll(".slot"));
      const elVariacion = document.getElementById("variacion");
      const btnBarajar = document.getElementById("btn-barajar");
      const btnTema = document.getElementById("btn-tema");
      const elReloj = document.getElementById("reloj");
      const elContadorOndas = document.getElementById("contador-ondas");

      function actualizarVariacion() {
        const n = 1 + estado[0] * 256 + estado[1] * 64 + estado[2] * 16 + estado[3] * 4 + estado[4];
        elVariacion.textContent = "lectura " + String(n).padStart(4, "0") + " / 1024";
      }

      function pintarSlot(indice, nuevoValor) {
        const btn = botonesSlot[indice];
        estado[indice] = nuevoValor;
        btn.classList.add("cambiando");
        window.setTimeout(function () {
          btn.textContent = opciones[indice][nuevoValor];
          btn.classList.remove("cambiando");
        }, 120);
      }

      botonesSlot.forEach(function (btn, idx) {
        btn.addEventListener("click", function () {
          const siguiente = (estado[idx] + 1) % opciones[idx].length;
          pintarSlot(idx, siguiente);
          actualizarVariacion();
        });
      });

      btnBarajar.addEventListener("click", function () {
        let cambio = false;
        for (let i = 0; i < estado.length; i++) {
          const elegido = Math.floor(Math.random() * opciones[i].length);
          if (elegido !== estado[i]) cambio = true;
          pintarSlot(i, elegido);
        }
        if (!cambio) {
          const azar = Math.floor(Math.random() * estado.length);
          pintarSlot(azar, (estado[azar] + 1) % opciones[azar].length);
        }
        actualizarVariacion();
      });

      let esNoche = false;
      btnTema.addEventListener("click", function () {
        esNoche = !esNoche;
        if (esNoche) {
          document.documentElement.setAttribute("data-theme", "night");
          btnTema.textContent = "papel";
          btnTema.setAttribute("aria-pressed", "true");
        } else {
          document.documentElement.removeAttribute("data-theme");
          btnTema.textContent = "noche";
          btnTema.setAttribute("aria-pressed", "false");
        }
        leerColoresCanvas();
      });

      const inicio = Date.now();
      window.setInterval(function () {
        const segs = Math.floor((Date.now() - inicio) / 1000);
        const m = String(Math.floor(segs / 60)).padStart(2, "0");
        const s = String(segs % 60).padStart(2, "0");
        elReloj.textContent = "aquí " + m + ":" + s;
      }, 1000);

      // Lienzo contemplativo de fondo
      const canvas = document.getElementById("campo");
      const ctx = canvas.getContext("2d");
      const reduceMotion = window.matchMedia("(prefers-reduced-motion: reduce)").matches;

      let ancho = 0;
      let alto = 0;
      let colorInk = "31, 30, 27";
      let colorAccent = "45, 77, 107";
      let totalTrazos = 0;

      function leerColoresCanvas() {
        const estilos = getComputedStyle(document.documentElement);
        colorInk = estilos.getPropertyValue("--canvas-ink").trim() || "31, 30, 27";
        colorAccent = estilos.getPropertyValue("--canvas-accent").trim() || "45, 77, 107";
      }

      const nodos = [];
      const ondas = [];
      const huellas = [];
      const puntero = { x: -9999, y: -9999, activo: false };

      function inicializarNodos() {
        nodos.length = 0;
        const cantidad = Math.min(46, Math.max(22, Math.floor((ancho * alto) / 28000)));
        for (let i = 0; i < cantidad; i++) {
          nodos.push({
            x: Math.random() * ancho,
            y: Math.random() * alto,
            vx: (Math.random() - 0.5) * 0.22,
            vy: (Math.random() - 0.5) * 0.22,
            r: 1.1 + Math.random() * 1.1
          });
        }
      }

      function redimensionar() {
        const dpr = Math.min(window.devicePixelRatio || 1, 2);
        ancho = window.innerWidth;
        alto = window.innerHeight;
        canvas.width = Math.floor(ancho * dpr);
        canvas.height = Math.floor(alto * dpr);
        ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
        if (nodos.length === 0) inicializarNodos();
      }

      function crearOnda(x, y) {
        ondas.push({ x: x, y: y, r: 4, maxR: 135, alpha: 0.42, vel: reduceMotion ? 0.45 : 0.85 });
        ondas.push({ x: x, y: y, r: 0, maxR: 85, alpha: 0.28, vel: reduceMotion ? 0.35 : 0.6 });
        huellas.push({ x: x, y: y, vida: 1 });
        totalTrazos += 1;
        elContadorOndas.textContent =
          totalTrazos === 1
            ? "1 trazo en esta visita"
            : totalTrazos + " trazos en esta visita";
      }

      window.addEventListener("pointermove", function (e) {
        puntero.x = e.clientX;
        puntero.y = e.clientY;
        puntero.activo = true;
      });

      window.addEventListener("pointerleave", function () {
        puntero.activo = false;
      });

      window.addEventListener("pointerdown", function (e) {
        if (e.target && e.target.closest("button, a")) return;
        crearOnda(e.clientX, e.clientY);
      });

      window.addEventListener("resize", redimensionar);

      function dibujar() {
        ctx.clearRect(0, 0, ancho, alto);

        // Nodos y vínculos suaves
        for (let i = 0; i < nodos.length; i++) {
          const n = nodos[i];
          if (!reduceMotion) {
            if (puntero.activo) {
              const dx = puntero.x - n.x;
              const dy = puntero.y - n.y;
              const dist = Math.hypot(dx, dy);
              if (dist > 12 && dist < 160) {
                n.vx += (dx / dist) * 0.004;
                n.vy += (dy / dist) * 0.004;
              }
            }
            n.vx *= 0.992;
            n.vy *= 0.992;
            const speed = Math.hypot(n.vx, n.vy);
            if (speed < 0.08) {
              n.vx += (Math.random() - 0.5) * 0.02;
              n.vy += (Math.random() - 0.5) * 0.02;
            }
            n.x += n.vx;
            n.y += n.vy;

            if (n.x < -20) n.x = ancho + 20;
            if (n.x > ancho + 20) n.x = -20;
            if (n.y < -20) n.y = alto + 20;
            if (n.y > alto + 20) n.y = -20;
          }

          ctx.beginPath();
          ctx.arc(n.x, n.y, n.r, 0, Math.PI * 2);
          ctx.fillStyle = "rgba(" + colorInk + ", 0.16)";
          ctx.fill();

          for (let j = i + 1; j < nodos.length; j++) {
            const m = nodos[j];
            const d = Math.hypot(n.x - m.x, n.y - m.y);
            if (d < 135) {
              const op = (1 - d / 135) * 0.085;
              ctx.beginPath();
              ctx.moveTo(n.x, n.y);
              ctx.lineTo(m.x, m.y);
              ctx.strokeStyle = "rgba(" + colorInk + ", " + op.toFixed(4) + ")";
              ctx.lineWidth = 0.8;
              ctx.stroke();
            }
          }
        }

        // Constelaciones efímeras dejadas al tocar el fondo
        for (let i = huellas.length - 1; i >= 0; i--) {
          const h = huellas[i];
          h.vida -= reduceMotion ? 0.0025 : 0.0042;
          if (h.vida <= 0) {
            huellas.splice(i, 1);
            continue;
          }

          ctx.beginPath();
          ctx.arc(h.x, h.y, 2.2, 0, Math.PI * 2);
          ctx.fillStyle = "rgba(" + colorAccent + ", " + (h.vida * 0.55).toFixed(3) + ")";
          ctx.fill();

          for (let k = 0; k < nodos.length; k++) {
            const n = nodos[k];
            const d = Math.hypot(h.x - n.x, h.y - n.y);
            if (d < 175) {
              const op = (1 - d / 175) * h.vida * 0.28;
              ctx.beginPath();
              ctx.moveTo(h.x, h.y);
              ctx.lineTo(n.x, n.y);
              ctx.strokeStyle = "rgba(" + colorAccent + ", " + op.toFixed(4) + ")";
              ctx.lineWidth = 0.9;
              ctx.stroke();
            }
          }
        }

        // Ondas concéntricas
        for (let i = ondas.length - 1; i >= 0; i--) {
          const o = ondas[i];
          o.r += o.vel;
          const progreso = o.r / o.maxR;
          if (progreso >= 1) {
            ondas.splice(i, 1);
            continue;
          }
          const op = o.alpha * (1 - progreso);
          ctx.beginPath();
          ctx.arc(o.x, o.y, o.r, 0, Math.PI * 2);
          ctx.strokeStyle = "rgba(" + colorAccent + ", " + op.toFixed(4) + ")";
          ctx.lineWidth = 1;
          ctx.stroke();
        }

        window.requestAnimationFrame(dibujar);
      }

      leerColoresCanvas();
      redimensionar();
      actualizarVariacion();
      window.requestAnimationFrame(dibujar);
    })();
  </script>
</body>
</html>
```

