          let siguiente;
          do {
            siguiente = Math.floor(Math.random() * ideas.length);
          } while (siguiente === índice);
          índice = siguiente;
          elementoIdea.textContent = ideas[índice];
          elementoIdea.classList.remove("cambiando");
        }, 200);
      });

