          ctx.fill();

          if (!reducirMovimiento) {
            p.y -= p.v;
            if (p.y < -3) {
              p.y = alto + 3;
              p.x = Math.random() * ancho;
            }
          }
        }

        if (!reducirMovimiento) cuadro = requestAnimationFrame(dibujar);
      }

      addEventListener("resize", () => {
        cancelAnimationFrame(cuadro);
        ajustar();
        dibujar();
      });

      ajustar();
      dibujar();
    })();
  </script>
