    (() => {
      const clock = document.querySelector("#clock");
      const phrase = document.querySelector("#phrase");
      const button = document.querySelector("#signalButton");
      const count = document.querySelector("#signal-count");
      const planet = document.querySelector(".planet");
      const canvas = document.querySelector("#sky");
      const ctx = canvas.getContext("2d");
      const reducedMotion = matchMedia("(prefers-reduced-motion: reduce)").matches;

      const phrases = [
        "No todo lo perdido quiere ser encontrado.",
        "La pausa también mueve las cosas.",
        "Hay preguntas que alumbran más que sus respuestas.",
        "Cambiar de idea es otra forma de llegar.",
        "Lo invisible también ocupa lugar.",
        "A veces el mapa aparece después del viaje.",
        "Prestá atención: lo mínimo está sucediendo.",
        "Toda puerta conserva la forma de una decisión.",
        "El silencio no siempre está vacío."
      ];

      let phraseIndex = 0;
      let stars = [];

      function updateClock() {
        clock.textContent = new Intl.DateTimeFormat("es-AR", {
          hour: "2-digit",
          minute: "2-digit",
          second: "2-digit",
          hour12: false
        }).format(new Date());
      }

      updateClock();
      setInterval(updateClock, 1000);

      button.addEventListener("click", () => {
        phrase.classList.add("changing");

        window.setTimeout(() => {
          phraseIndex = (phraseIndex + 1) % phrases.length;
          phrase.textContent = phrases[phraseIndex];
          count.textContent = `Señal ${String(phraseIndex + 1).padStart(2, "0")}`;
          phrase.classList.remove("changing");
        }, 180);
      });

      if (!reducedMotion) {
        document.querySelector(".hero").addEventListener("pointermove", event => {
          const rect = event.currentTarget.getBoundingClientRect();
          const x = (event.clientX - rect.left) / rect.width - .5;
          const y = (event.clientY - rect.top) / rect.height - .5;
          planet.style.setProperty("--x", `${x * 28}px`);
          planet.style.setProperty("--y", `${y * 28}px`);
        });

        document.querySelector(".hero").addEventListener("pointerleave", () => {
          planet.style.setProperty("--x", "0px");
          planet.style.setProperty("--y", "0px");
        });
      }

      function resizeSky() {
        const ratio = Math.min(devicePixelRatio || 1, 2);
        const rect = canvas.getBoundingClientRect();

        canvas.width = Math.floor(rect.width * ratio);
        canvas.height = Math.floor(rect.height * ratio);
        ctx.setTransform(ratio, 0, 0, ratio, 0, 0);

        const amount = Math.floor((rect.width * rect.height) / 15000);
        stars = Array.from({ length: amount }, () => ({
          x: Math.random() * rect.width,
          y: Math.random() * rect.height,
          r: Math.random() * 1.2 + .2,
          a: Math.random() * .65 + .15,
          speed: Math.random() * .008 + .002,
          phase: Math.random() * Math.PI * 2
        }));

        drawSky(0);
      }

      function drawSky(time) {
        const rect = canvas.getBoundingClientRect();
        ctx.clearRect(0, 0, rect.width, rect.height);

        for (const star of stars) {
          const alpha = reducedMotion
            ? star.a
            : star.a * (.6 + Math.sin(time * star.speed + star.phase) * .4);

          ctx.beginPath();
          ctx.fillStyle = `rgba(232,226,213,${Math.max(.05, alpha)})`;
          ctx.arc(star.x, star.y, star.r, 0, Math.PI * 2);
          ctx.fill();
        }

        if (!reducedMotion) requestAnimationFrame(drawSky);
      }

      resizeSky();
      addEventListener("resize", resizeSky);

      if (!reducedMotion) requestAnimationFrame(drawSky);
    })();
  </script>
