        const valor = Number(luz.value);
        const posicion = (valor - 50) / 50;
        const x = 240 + posicion * 180;
        const y = 75 + posicion * posicion * 89;
        const escala = -posicion * 1.65;
        const angulo = -posicion * 17;

        sol.setAttribute('transform', `translate(${x} ${y})`);
