    (() => {
      const ideas = [
        [
          "Una biblioteca",
          "donde los libros se ordenan por las preguntas que te dejan, no por las respuestas que contienen."
        ],
        [
          "Un mapa",
          "que no te muestra el camino más corto, sino el que tiene un árbol bajo el cual detenerse."
        ],
        [
          "Un museo de borradores",
          "donde cada obra está acompañada por todo lo que tuvo que dejar de ser."
        ],
        [
          "Un diccionario provisional",
          "con palabras para las cosas que reconocemos enseguida, pero todavía no sabemos nombrar."
        ],
        [
          "Una plaza",
          "con una mesa lo bastante larga como para que dos conversaciones terminen encontrándose."
        ],
        [
          "Un reloj distinto",
          "que no cuenta cuánto tardaste, sino cuántas veces cambiaste de idea."
        ]
      ];

      let actual = 0;
      const boton = document.getElementById("otra");
      const titulo = document.getElementById("idea-titulo");
      const texto = document.getElementById("idea-texto");
      const contador = document.getElementById("contador");

      boton.hidden = false;
      boton.addEventListener("click", () => {
        actual = (actual + 1) % ideas.length;
        titulo.textContent = ideas[actual][0];
        texto.textContent = ideas[actual][1];
        contador.textContent =
          String(actual + 1).padStart(2, "0") + " / " +
          String(ideas.length).padStart(2, "0");
      });
    })();
  </script>
