    ];

    const button = document.getElementById("question-button");
    const thought = document.getElementById("thought-text");
    let previous = 0;

    button.addEventListener("click", () => {
      let next;
      do {
        next = Math.floor(Math.random() * ideas.length);
      } while (next === previous);
      previous = next;
      thought.innerHTML = ideas[next];
      thought.focus?.();
