  <script>
    const notas = [
      "No todo lo que crece hace ruido.",
      "Dejá una ventana abierta para la sorpresa.",
      "Una pausa también puede ser parte del camino.",
      "Hay días que solo piden ser atravesados con amabilidad.",
      "Mirá de nuevo: quizás algo cambió mientras no mirabas.",
      "No hace falta convertir cada curiosidad en una tarea.",
      "A veces, el siguiente paso es dejar de apurarse."
    ];

    const boton = document.querySelector("#boton-nota");
    const salida = document.querySelector("#nota");
    let anterior = notas.length - 1;

    boton.addEventListener("click", () => {
      let indice;
      do {
        indice = Math.floor(Math.random() * notas.length);
      } while (indice === anterior);

      anterior = indice;
      salida.textContent = notas[indice];
    });
  </script>
