    var h=Math.floor(m/60), m2=m%60;
    reloj.textContent = h>0 ? h+':'+pad(m2)+':'+pad(ss) : m+':'+pad(ss);
  }
  setInterval(tick,1000);
  tick();

  document.getElementById('anio').textContent=fecha.getFullYear();
})();
