<script>
(function () {
  var canvas = document.getElementById('field');
  var ctx    = canvas.getContext('2d');
  var W, H, dots;
  var mx = -9999, my = -9999;

  function resize () {
    W = canvas.width  = window.innerWidth;
    H = canvas.height = window.innerHeight;
  }

  function build () {
    dots = [];
    var n = Math.min(Math.floor(W * H / 13000), 90);
    for (var i = 0; i < n; i++) {
      dots.push({
        x: Math.random() * W,
        y: Math.random() * H,
        vx: (Math.random() - .5) * .22,
        vy: (Math.random() - .5) * .22,
        r: Math.random() * 1.15 + .35,
        a: Math.random() * .3 + .08
      });
    }
  }

  function frame () {
    ctx.clearRect(0, 0, W, H);

    for (var i = 0; i < dots.length; i++) {
      var p = dots[i];

      p.x += p.vx;
      p.y += p.vy;

      if (p.x < -15) p.x = W + 15;
      if (p.x > W + 15) p.x = -15;
      if (p.y < -15) p.y = H + 15;
      if (p.y > H + 15) p.y = -15;

      ctx.beginPath();
      ctx.arc(p.x, p.y, p.r, 0, 6.2832);
      ctx.fillStyle = 'rgba(200,185,155,' + p.a + ')';
      ctx.fill();

      for (var j = i + 1; j < dots.length; j++) {
        var q = dots[j];
        var dx = p.x - q.x, dy = p.y - q.y;
        var d = Math.sqrt(dx * dx + dy * dy);
        if (d < 130) {
          ctx.beginPath();
          ctx.moveTo(p.x, p.y);
          ctx.lineTo(q.x, q.y);
          ctx.strokeStyle = 'rgba(200,185,155,' + (.04 * (1 - d / 130)) + ')';
          ctx.lineWidth = .5;
          ctx.stroke();
        }
      }

      var mDx = p.x - mx, mDy = p.y - my;
      var md = Math.sqrt(mDx * mDx + mDy * mDy);
      if (md < 155) {
        ctx.beginPath();
        ctx.moveTo(p.x, p.y);
        ctx.lineTo(mx, my);
        ctx.strokeStyle = 'rgba(201,168,76,' + (.13 * (1 - md / 155)) + ')';
        ctx.lineWidth = .5;
        ctx.stroke();

        p.vx += (mx - p.x) * .000025;
        p.vy += (my - p.y) * .000025;
      }
    }

    requestAnimationFrame(frame);
  }

  window.addEventListener('resize', function () { resize(); build(); });
  window.addEventListener('mousemove', function (e) { mx = e.clientX; my = e.clientY; });
  window.addEventListener('mouseout',  function ()  { mx = -9999; my = -9999; });
  window.addEventListener('touchmove', function (e) {
    if (e.touches[0]) { mx = e.touches[0].clientX; my = e.touches[0].clientY; }
  }, { passive: true });
  window.addEventListener('touchend', function () { mx = -9999; my = -9999; });

  resize(); build(); frame();
})();
</script>

</body>
</html>
