html{scroll-behavior:smooth}

body{
  background:var(--bg);color:var(--text);
  font-family:var(--serif);line-height:1.85;
  overflow-x:hidden;
}

/* vignette overlay */
body::after{
  content:'';position:fixed;inset:0;z-index:2;pointer-events:none;
  background:radial-gradient(ellipse at center,transparent 55%,rgba(0,0,0,0.55) 100%);
}

#canvas-bg{
  position:fixed;top:0;left:0;width:100%;height:100%;
  z-index:0;pointer-events:none;
}

.wrap{
  position:relative;z-index:3;
  max-width:680px;margin:0 auto;padding:0 2.2rem;
}

/* ── hero ── */
.hero{
  min-height:100vh;display:flex;flex-direction:column;
  justify-content:center;align-items:center;
  text-align:center;position:relative;
}

.hero h1{
  font-size:clamp(2.6rem,7vw,5.2rem);font-weight:400;
  letter-spacing:.18em;color:var(--text);
  opacity:0;animation:rise 2.2s cubic-bezier(.22,1,.36,1) .4s forwards;
}

.hero .line{
  width:64px;height:1px;background:var(--gold);
  margin:2.2rem auto;opacity:0;
  animation:lineGrow 1.8s cubic-bezier(.22,1,.36,1) .9s forwards;
}

.hero .sub{
  font-family:var(--sans);font-size:.82rem;letter-spacing:.32em;
  text-transform:uppercase;color:var(--dim);
  opacity:0;animation:rise 2.2s cubic-bezier(.22,1,.36,1) 1.3s forwards;
}

.scroll-hint{
  position:absolute;bottom:2.4rem;left:50%;transform:translateX(-50%);
  display:flex;flex-direction:column;align-items:center;gap:.6rem;
  cursor:pointer;opacity:0;
  animation:rise 2s ease 2.6s forwards;
}

.scroll-hint span{
  font-family:var(--sans);font-size:.62rem;letter-spacing:.32em;
  text-transform:uppercase;color:var(--dim);
}

.scroll-hint .arrow{
  width:1px;height:32px;
  background:linear-gradient(to bottom,var(--dim),transparent);
  animation:bounce 2.2s ease-in-out infinite;
}

/* ── sections ── */
section{
  padding:6.5rem 0;
  opacity:0;transform:translateY(42px);
  transition:opacity 1.3s ease,transform 1.3s ease;
}
section.vis{opacity:1;transform:translateY(0)}

.label{
  font-family:var(--sans);font-size:.68rem;
  letter-spacing:.36em;text-transform:uppercase;
  color:var(--gold);margin-bottom:1.6rem;
}

section p{
  font-size:1.14rem;margin-bottom:1.4rem;
}
section p.dim{
  color:var(--dim);font-size:1.02rem;
}

.quote{
  font-size:1.55rem;font-style:italic;line-height:2.1;
  color:var(--violet);padding-left:1.6rem;
  border-left:1px solid var(--violet);
  margin:3.2rem 0;
}

.divider{
  width:40px;height:1px;margin:3.2rem auto;
  background:linear-gradient(90deg,transparent,var(--gold),transparent);
}

/* ── interactive ── */
#inter{text-align:center}
#inter canvas{
  display:block;width:100%;max-width:580px;height:280px;
  margin:2.2rem auto 0;border:1px solid rgba(212,168,83,.12);
  border-radius:5px;cursor:crosshair;
}

/* ── footer ── */
footer{
  padding:4.5rem 0 3.5rem;text-align:center;
  font-family:var(--sans);font-size:.72rem;
  letter-spacing:.22em;color:var(--dim);
}
footer .dot{
  width:5px;height:5px;border-radius:50%;
  background:var(--gold);margin:0 auto 1.8rem;
  animation:pulse 3s ease-in-out infinite;
}
footer .soft{opacity:.35;margin-top:.6rem;letter-spacing:.3em}

/* ── keyframes ── */
@keyframes rise{
  from{opacity:0;transform:translateY(32px)}
  to{opacity:1;transform:translateY(0)}
}
@keyframes lineGrow{
  from{opacity:0;transform:scaleX(0)}
  to{opacity:1;transform:scaleX(1)}
}
@keyframes bounce{
  0%,100%{transform:translateY(0);opacity:1}
  50%{transform:translateY(12px);opacity:.25}
}
@keyframes pulse{
  0%,100%{opacity:.25}50%{opacity:1}
}
</style>
