<script>
/* ══════════════════════════════════════
   BACKGROUND — starfield + constellations
   ══════════════════════════════════════ */
(function(){
  const cv=document.getElementById('canvas-bg'),cx=cv.getContext('2d');
  let W,H,stars=[],mx=-9e3,my=-9e3;

  function fit(){W=cv.width=innerWidth;H=cv.height=innerHeight}
  fit();addEventListener('resize',fit);

  const N=Math.min(130,Math.floor(innerWidth*innerHeight/11000));
  for(let i=0;i<N;i++)stars.push({
    x:Math.random()*W,y:Math.random()*H,
    vx:(Math.random()-.5)*.28,vy:(Math.random()-.5)*.28,
    r:Math.random()*1.4+.5,
    a:Math.random()*.45+.18,t:Math.random()*6.28
  });

  addEventListener('mousemove',e=>{mx=e.clientX;my=e.clientY});

  (function loop(){
    cx.clearRect(0,0,W,H);

    for(const s of stars){
      s.x+=s.vx;s.y+=s.vy;s.t+=.012;
      if(s.x<-8)s.x=W+8;if(s.x>W+8)s.x=-8;
      if(s.y<-8)s.y=H+8;if(s.y>H+8)s.y=-8;

      const dx=mx-s.x,dy=my-s.y,d=Math.sqrt(dx*dx+dy*dy);
      if(d<190){const f=(190-d)/190;s.x-=dx*f*.008;s.y-=dy*f*.008}

      const alpha=s.a+Math.sin(s.t)*.14;
      cx.beginPath();cx.arc(s.x,s.y,s.r,0,6.283);
      cx.fillStyle='rgba(200,194,184,'+Math.max(0,alpha)+')';cx.fill();

      if(d<140){
        const g=(140-d)/140*.13;
        cx.beginPath();cx.arc(s.x,s.y,s.r*3,0,6.283);
        cx.fillStyle='rgba(212,168,83,'+g+')';cx.fill();
      }
    }

    for(let i=0;i<stars.length;i++){
      for(let j=i+1;j<stars.length;j++){
        const dx=stars[i].x-stars[j].x,dy=stars[i].y-stars[j].y;
        const d=Math.sqrt(dx*dx+dy*dy);
        if(d<115){
          cx.beginPath();cx.moveTo(stars[i].x,stars[i].y);
          cx.lineTo(stars[j].x,stars[j].y);
          cx.strokeStyle='rgba(139,126,200,'+((115-d)/115*.07)+')';
          cx.lineWidth=.5;cx.stroke();
        }
      }
    }
    requestAnimationFrame(loop);
  })();
})();

/* ══════════════════════════════════════
   INTERACTIVE — luminous field
   ══════════════════════════════════════ */
(function(){
  const cv=document.getElementById('lumi'),cx=cv.getContext('2d');
  let pts=[],m={x:-1,y:-1,on:false};
  let cw,ch;

  function fit(){
    const r=cv.getBoundingClientRect();
    cw=r.width;ch=r.height;
    cv.width=cw*2;cv.height=ch*2;
    cx.setTransform(2,0,0,2,0,0);
    cx.fillStyle='#080810';cx.fillRect(0,0,cw,ch);
  }
  fit();addEventListener('resize',fit);

  for(let i=0;i<75;i++)pts.push({
    x:Math.random()*290,y:Math.random()*140,
    vx:(Math.random()-.5)*.45,vy:(Math.random()-.5)*.45,
    r:Math.random()*1.8+.8,hue:Math.random()*38+22
  });

  cv.addEventListener('mousemove',e=>{
    const r=cv.getBoundingClientRect();
    m.x=e.clientX-r.left;m.y=e.clientY-r.top;m.on=true;
  });
  cv.addEventListener('mouseleave',()=>m.on=false);
  cv.addEventListener('touchmove',e=>{
    e.preventDefault();
    const r=cv.getBoundingClientRect();
    const t=e.touches[0];
    m.x=t.clientX-r.left;m.y=t.clientY-r.top;m.on=true;
  },{passive:false});
  cv.addEventListener('touchend',()=>m.on=false);

  (function loop(){
    cx.fillStyle='rgba(8,8,16,0.12)';cx.fillRect(0,0,cw,ch);

    for(const p of pts){
      p.x+=p.vx;p.y+=p.vy;

      if(m.on){
        const dx=m.x-p.x,dy=m.y-p.y,d=Math.sqrt(dx*dx+dy*dy);
        if(d<130&&d>1){const f=(130-d)/130;p.x+=dx*f*.032;p.y+=dy*f*.032}
      }

      if(p.x<0||p.x>cw)p.vx*=-1;
      if(p.y<0||p.y>ch)p.vy*=-1;
      p.x=Math.max(0,Math.min(cw,p.x));
      p.y=Math.max(0,Math.min(ch,p.y));

      const g=cx.createRadialGradient(p.x,p.y,0,p.x,p.y,p.r*5);
      g.addColorStop(0,'hsla('+p.hue+',80%,72%,.75)');
      g.addColorStop(1,'hsla('+p.hue+',80%,72%,0)');
      cx.beginPath();cx.arc(p.x,p.y,p.r*5,0,6.283);cx.fillStyle=g;cx.fill();

      cx.beginPath();cx.arc(p.x,p.y,p.r*.45,0,6.283);
      cx.fillStyle='hsla('+p.hue+',55%,92%,.88)';cx.fill();
    }

    for(let i=0;i<pts.length;i++){
      for(let j=i+1;j<pts.length;j++){
        const dx=pts[i].x-pts[j].x,dy=pts[i].y-pts[j].y,d=Math.sqrt(dx*dx+dy*dy);
        if(d<75){
          cx.beginPath();cx.moveTo(pts[i].x,pts[i].y);cx.lineTo(pts[j].x,pts[j].y);
          cx.strokeStyle='rgba(212,168,83,'+((75-d)/75*.1)+')';
          cx.lineWidth=.5;cx.stroke();
        }
      }
    }
    requestAnimationFrame(loop);
  })();
})();

/* ══════════════════════════════════════
   SCROLL REVEAL
   ══════════════════════════════════════ */
(function(){
  const obs=new IntersectionObserver(es=>{
    es.forEach(e=>{if(e.isIntersecting)e.target.classList.add('vis')});
  },{threshold:.12});
  document.querySelectorAll('section').forEach(s=>{
    if(!s.classList.contains('hero'))obs.observe(s);
  });
})();

/* scroll down */
document.getElementById('scrollDown').addEventListener('click',()=>{
  window.scrollBy({top:innerHeight,behavior:'smooth'});
});
</script>

</body>
