<script>
// Background constellation canvas
const bgCanvas = document.getElementById('canvas-bg');
const bgCtx = bgCanvas.getContext('2d');
let W, H;
let particles = [];
let mouse = { x: -1000, y: -1000 };

function resize() {
  W = bgCanvas.width = window.innerWidth;
  H = bgCanvas.height = window.innerHeight;
}
resize();
window.addEventListener('resize', resize);

// Create particles
const PARTICLE_COUNT = Math.min(120, Math.floor(window.innerWidth * window.innerHeight / 12000));

for (let i = 0; i < PARTICLE_COUNT; i++) {
  particles.push({
    x: Math.random() * W,
    y: Math.random() * H,
    vx: (Math.random() - 0.5) * 0.3,
    vy: (Math.random() - 0.5) * 0.3,
    r: Math.random() * 1.5 + 0.5,
    alpha: Math.random() * 0.5 + 0.2,
    twinkle: Math.random() * Math.PI * 2
  });
}

document.addEventListener('mousemove', e => {
  mouse.x = e.clientX;
  mouse.y = e.clientY;
});

function drawBg() {
  bgCtx.clearRect(0, 0, W, H);

  particles.forEach(p => {
    p.x += p.vx;
    p.y += p.vy;
    p.twinkle += 0.01;

    // Wrap around
    if (p.x < -10) p.x = W + 10;
    if (p.x > W + 10) p.x = -10;
    if (p.y < -10) p.y = H + 10;
    if (p.y > H + 10) p.y = -10;

    // Mouse influence
    const dx = mouse.x - p.x;
    const dy = mouse.y - p.y;
    const dist = Math.sqrt(dx * dx + dy * dy);
    if (dist < 200) {
      const force = (200 - dist) / 200;
      p.x -= dx * force * 0.01;
      p.y -= dy * force * 0.01;
    }

    const twinkleAlpha = p.alpha + Math.sin(p.twinkle) * 0.15;

    // Draw particle
    bgCtx.beginPath();
    bgCtx.arc(p.x, p.y, p.r, 0, Math.PI * 2);
    bgCtx.fillStyle = `rgba(200, 194, 184, ${Math.max(0, twinkleAlpha)})`;
    bgCtx.fill();

    // Glow near mouse
    if (dist < 150) {
      const glowAlpha = (150 - dist) / 150 * 0.15;
      bgCtx.beginPath();
      bgCtx.arc(p.x, p.y, p.r * 3, 0, Math.PI * 2);
      bgCtx.fillStyle = `rgba(212, 168, 83, ${glowAlpha})`;
      bgCtx.fill();
    }
  });

  // Draw connections
  for (let i = 0; i < particles.length; i++) {
    for (let j = i + 1; j < particles.length; j++) {
      const dx = particles[i].x - particles[j].x;
      const dy = particles[i].y - particles[j].y;
      const dist = Math.sqrt(dx * dx + dy * dy);

      if (dist < 120) {
        const alpha = (120 - dist) / 120 * 0.08;
        bgCtx.beginPath();
        bgCtx.moveTo(particles[i].x, particles[i].y);
        bgCtx.lineTo(particles[j].x, particles[j].y);
        bgCtx.strokeStyle = `rgba(139, 126, 200, ${alpha})`;
        bgCtx.lineWidth = 0.5;
        bgCtx.stroke();
      }
    }
  }

  requestAnimationFrame(drawBg);
}
drawBg();

// Interactive luminous canvas
const lumiCanvas = document.getElementById('lumi-canvas');
const lumiCtx = lumiCanvas.getContext('2d');
let lumiParticles = [];
let lumiMouse = { x: -100, y: -100, active: false };

function resizeLumi() {
  const rect = lumiCanvas.getBoundingClientRect();
  lumiCanvas.width = rect.width * 2;
  lumiCanvas.height = rect.height * 2;
  lumiCtx.scale(2, 2);
}
resizeLumi();
window.addEventListener('resize', resizeLumi);

// Lumi particles
for (let i = 0; i < 80; i++) {
  lumiParticles.push({
    x: Math.random() * 300,
    y: Math.random() * 150,
    vx: (Math.random() - 0.5) * 0.5,
    vy: (Math.random() - 0.5) * 0.5,
    r: Math.random() * 2 + 1,
    hue: Math.random() * 40 + 20 // warm hues
  });
}

lumiCanvas.addEventListener('mousemove', e => {
  const rect = lumiCanvas.getBoundingClientRect();
  lumiMouse.x = e.clientX - rect.left;
  lumiMouse.y = e.clientY - rect.top;
  lumiMouse.active = true;
});

lumiCanvas.addEventListener('mouseleave', () => {
  lumiMouse.active = false;
});

function drawLumi() {
  const w = lumiCanvas.width / 2;
  const h = lumiCanvas.height / 2;

  lumiCtx.fillStyle = 'rgba(8, 8, 16, 0.15)';
  lumiCtx.fillRect(0, 0, w, h);

  lumiParticles.forEach(p => {
    p.x += p.vx;
    p.y += p.vy;

    // Mouse attraction
    if (lumiMouse.active) {
      const dx = lumiMouse.x - p.x;
      const dy = lumiMouse.y - p.y;
      const dist = Math.sqrt(dx * dx + dy * dy);
      if (dist < 120 && dist > 0) {
        const force = (120 - dist) / 120;
        p.x += dx * force * 0.03;
        p.y += dy * force * 0.03;
      }
    }

    // Bounce
    if (p.x < 0 || p.x > w) p.vx *= -1;
    if (p.y < 0 || p.y > h) p.vy *= -1;

    p.x = Math.max(0, Math.min(w, p.x));
    p.y = Math.max(0, Math.min(h, p.y));

    // Draw
    const gradient = lumiCtx.createRadialGradient(p.x, p.y, 0, p.x, p.y, p.r * 4);
    gradient.addColorStop(0, `hsla(${p.hue}, 80%, 70%, 0.8)`);
    gradient.addColorStop(1, `hsla(${p.hue}, 80%, 70%, 0)`);
    lumiCtx.beginPath();
    lumiCtx.arc(p.x, p.y, p.r * 4, 0, Math.PI * 2);
    lumiCtx.fillStyle = gradient;
    lumiCtx.fill();

    // Core
    lumiCtx.beginPath();
    lumiCtx.arc(p.x, p.y, p.r * 0.5, 0, Math.PI * 2);
    lumiCtx.fillStyle = `hsla(${p.hue}, 60%, 90%, 0.9)`;
    lumiCtx.fill();
  });

  // Draw connections in lumi
  for (let i = 0; i < lumiParticles.length; i++) {
    for (let j = i + 1; j < lumiParticles.length; j++) {
      const dx = lumiParticles[i].x - lumiParticles[j].x;
      const dy = lumiParticles[i].y - lumiParticles[j].y;
      const dist = Math.sqrt(dx * dx + dy * dy);
      if (dist < 80) {
        lumiCtx.beginPath();
        lumiCtx.moveTo(lumiParticles[i].x, lumiParticles[i].y);
        lumiCtx.lineTo(lumiParticles[j].x, lumiParticles[j].y);
        lumiCtx.strokeStyle = `rgba(212, 168, 83, ${(80 - dist) / 80 * 0.12})`;
        lumiCtx.lineWidth = 0.5;
        lumiCtx.stroke();
      }
    }
  }

  requestAnimationFrame(drawLumi);
}
drawLumi();

// Scroll reveal
const observer = new IntersectionObserver((entries) => {
  entries.forEach(entry => {
    if (entry.isIntersecting) {
      entry.target.classList.add('visible');
    }
  });
}, { threshold: 0.15 });

document.querySelectorAll('section').forEach(s => observer.observe(s));

// Smooth scroll for hero
document.querySelector('.scroll-hint').addEventListener('click', () => {
  window.scrollBy({ top: window.innerHeight, behavior: 'smooth' });
});
</script>

</body>
</html>
