  }

  window.addEventListener('resize', resize);

  window.addEventListener('mousemove', function(e){
    mouse.x = e.clientX / W - 0.5;
    mouse.y = e.clientY / H - 0.5;
  });

  window.addEventListener('click', function(e){
    const ang = Math.random() * Math.PI * 2;
    fugaces.push({ x: e.clientX, y: e.clientY, vx: Math.cos(ang) * 7, vy: Math.sin(ang) * 7, vida: 1 });
  });

  function dibujar(){
    const T = temas[tema];
    ctx.clearRect(0, 0, W, H);

    ctx.lineWidth = 1;
    for(let i = 0; i < estrellas.length; i++){
      const a = estrellas[i];
      for(let j = i + 1; j < estrellas.length; j++){
        const b = estrellas[j];
        const dx = a.x - b.x, dy = a.y - b.y;
        const d = dx * dx + dy * dy;
        if(d < 9000){
          ctx.strokeStyle = 'rgba(' + T.linea + ',' + ((1 - d / 9000) * 0.16).toFixed(3) + ')';
          ctx.beginPath();
          ctx.moveTo(a.x, a.y);
          ctx.lineTo(b.x, b.y);
