      }
      const tw = reduced ? 0.8 : 0.55 + 0.45 * Math.sin(e.f);
      const px = e.x + mouse.x * 42 * e.p;
      const py = e.y + mouse.y * 42 * e.p;
      ctx.fillStyle = 'rgba(' + T.puntos[e.c] + ',' + tw.toFixed(3) + ')';
      ctx.beginPath();
