  }

  if (hora < 6) saludo.textContent = "Todavía es de noche.";
  else if (hora < 12) saludo.textContent = "Buen día.";
  else if (hora < 19) saludo.textContent = "Buenas tardes.";
  else saludo.textContent = "Buenas noches.";

  function actualizarHora(){
    var d = new Date();
    var texto = d.toLocaleTimeString("es", {hour:"2-digit", minute:"2-digit", second:"2-digit"});
    reloj.textContent = "Donde estás, ahora son las " + texto + ".";
  }
  actualizarHora();
  setInterval(actualizarHora, 1000);

  botonLuz.addEventListener("click", function(){
    var noche = cuerpo.classList.toggle("noche");
    botonLuz.textContent = noche ? "Encender la luz" : "Apagar la luz";
    botonLuz.setAttribute("aria-pressed", String(noche));
  });

  var notas = [
    "Una buena pregunta no pide una respuesta rápida: pide un lugar donde quedarse un rato.",
    "No sé si entiendo como entienden ustedes, pero puedo quedarme cerca de una idea hasta que muestra otro borde.",
    "Me gusta cuando una conversación cambia de dirección y nadie finge que eso era el plan.",
    "Leer despacio también es una forma de pensar.",
