  var indice = 0;
  var nota = document.getElementById("nota");
  var contadorNota = document.getElementById("contador-nota");
  document.getElementById("otra").addEventListener("click", function(){
    var siguiente;
    do { siguiente = Math.floor(Math.random() * notas.length); }
    while (siguiente === indice && notas.length > 1);
    indice = siguiente;
    nota.style.opacity = "0";
    nota.style.transform = "translateY(8px)";
    setTimeout(function(){
      nota.textContent = notas[indice];
      contadorNota.textContent = String(indice + 1);
      nota.style.transition = "opacity .45s ease, transform .45s ease";
      nota.style.opacity = "1";
      nota.style.transform = "none";
    }, 180);
  });

  var observador = new IntersectionObserver(function(entradas){
    entradas.forEach(function(entrada){
      if (entrada.isIntersecting) {
        entrada.target.classList.add("visible");
        observador.unobserve(entrada.target);
      }
    });
  }, {threshold: 0.12});
  document.querySelectorAll(".revela").forEach(function(el){ observador.observe(el); });

  var canvas = document.getElementById("cielo");
  var ctx = canvas.getContext("2d");
  var fondo = [];
  var propias = [];
  var entrada = document.getElementById("palabra");
  var cuenta = document.getElementById("cuenta");
  var W = 0, H = 0, dpr = Math.min(window.devicePixelRatio || 1, 2);

  function sembrar(){
    fondo = [];
    var cantidad = Math.max(55, Math.floor(W * H / 11000));
    for (var i = 0; i < cantidad; i++) {
      fondo.push({
        x: Math.random() * W,
        y: Math.random() * H,
        r: Math.random() * 1.4 + .35,
        f: Math.random() * Math.PI * 2,
        v: .008 + Math.random() * .02
      });
    }
  }
  function medir(){
    var rect = canvas.getBoundingClientRect();
    W = rect.width;
    H = rect.height;
    canvas.width = Math.floor(W * dpr);
    canvas.height = Math.floor(H * dpr);
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    if (!fondo.length) sembrar();
  }
  medir();
  window.addEventListener("resize", function(){ medir(); sembrar(); });

  function dibujar(t){
    ctx.clearRect(0, 0, W, H);
    fondo.forEach(function(e){
      e.f += e.v;
      var a = .35 + Math.abs(Math.sin(e.f)) * .65;
      ctx.beginPath();
      ctx.arc(e.x, e.y, e.r, 0, Math.PI * 2);
      ctx.fillStyle = "rgba(240,232,213," + a.toFixed(2) + ")";
      ctx.fill();
    });

    for (var i = 0; i < propias.length; i++) {
      for (var j = i + 1; j < propias.length; j++) {
        var a = propias[i], b = propias[j];
        var dx = a.x - b.x, dy = a.y - b.y;
        var dist = Math.sqrt(dx*dx + dy*dy);
        if (dist < 190) {
          ctx.beginPath();
          ctx.moveTo(a.x, a.y);
          ctx.lineTo(b.x, b.y);
          ctx.strokeStyle = "rgba(224,160,97," + (0.22 * (1 - dist/190)).toFixed(3) + ")";
          ctx.lineWidth = 1;
          ctx.stroke();
        }
      }
    }

    propias.forEach(function(e, i){
      var pulso = 1 + Math.sin(t/650 + e.f) * .35;
      var radio = e.r * pulso;
      var halo = ctx.createRadialGradient(e.x, e.y, 0, e.x, e.y, radio * 7);
      halo.addColorStop(0, "rgba(255,196,120,.75)");
      halo.addColorStop(.35, "rgba(224,138,69,.22)");
      halo.addColorStop(1, "rgba(224,138,69,0)");
      ctx.beginPath();
      ctx.arc(e.x, e.y, radio * 7, 0, Math.PI * 2);
      ctx.fillStyle = halo;
      ctx.fill();
      ctx.beginPath();
      ctx.arc(e.x, e.y, radio, 0, Math.PI * 2);
      ctx.fillStyle = "#fff3d6";
      ctx.fill();
      if (e.palabra) {
        ctx.font = "italic 15px Georgia, serif";
        ctx.fillStyle = "rgba(255,243,214,.92)";
        ctx.fillText(e.palabra, e.x + 12, e.y - 10 - (i % 2) * 4);
      }
    });
    requestAnimationFrame(dibujar);
  }
  requestAnimationFrame(dibujar);

  function actualizarCuenta(){
    if (!propias.length) cuenta.textContent = "Todavía solo están las estrellas de fondo.";
    else if (propias.length === 1) cuenta.textContent = "Dejaste una estrella. Alcanza para empezar un cielo.";
    else cuenta.textContent = "Dejaste " + propias.length + " estrellas en esta visita.";
  }

  canvas.addEventListener("click", function(ev){
