      </div>
    </section>
  </main>

  <footer class="sube" style="animation-delay:1s">
    <p>Un solo archivo, sin recursos de afuera, sin cookies, sin memoria. Las letras del fondo son lo único que se mueve y no significan nada hasta que alguien las lee.</p>
    <p class="mono">hecha de una sola vez</p>
  </footer>
</div>

<script>
(function(){
  "use strict";
  var root = document.documentElement;
  var reducido = window.matchMedia && matchMedia('(prefers-reduced-motion: reduce)').matches;

  /* ---------- la luz según la hora ---------- */
  var paradas = [
    {h:0,    bg:[10,12,20],    ink:[232,230,223], ac:[127,176,201], n:'madrugada'},
    {h:5.5,  bg:[26,20,32],    ink:[242,228,216], ac:[224,138,92],  n:'amanecer'},
    {h:8.5,  bg:[244,240,230], ink:[35,32,28],    ac:[180,85,47],   n:'mañana'},
    {h:13,   bg:[251,250,246], ink:[28,27,24],    ac:[47,107,90],   n:'mediodía'},
    {h:18,   bg:[239,227,214], ink:[42,33,28],    ac:[192,96,58],   n:'tarde'},
    {h:20.5, bg:[23,26,36],    ink:[230,230,224], ac:[142,169,216], n:'noche'},
    {h:24,   bg:[10,12,20],    ink:[232,230,223], ac:[127,176,201], n:'madrugada'}
  ];
  function lerp(a,b,t){return a+(b-a)*t;}
  function mezcla(a,b,t){return [Math.round(lerp(a[0],b[0],t)),Math.round(lerp(a[1],b[1],t)),Math.round(lerp(a[2],b[2],t))];}
  function rgb(c){return 'rgb('+c[0]+','+c[1]+','+c[2]+')';}
  function rgba(c,a){return 'rgba('+c[0]+','+c[1]+','+c[2]+','+a+')';}
  function suave(t){return t*t*(3-2*t);}
  function paleta(h){
    h=((h%24)+24)%24;
    for(var i=0;i<paradas.length-1;i++){
      var a=paradas[i], b=paradas[i+1];
      if(h>=a.h && h<=b.h){
        var t=suave((h-a.h)/(b.h-a.h));
        return {bg:mezcla(a.bg,b.bg,t), ink:mezcla(a.ink,b.ink,t), ac:mezcla(a.ac,b.ac,t), n:(t<.5?a.n:b.n)};
      }
    }
    return {bg:paradas[0].bg, ink:paradas[0].ink, ac:paradas[0].ac, n:paradas[0].n};
  }
  function dos(n){return (n<10?'0':'')+n;}
  function formato(h){var H=Math.floor(h)%24, M=Math.floor((h-Math.floor(h))*60);return dos(H)+':'+dos(M);}
  function horaTuya(){var d=new Date();return d.getHours()+d.getMinutes()/60+d.getSeconds()/3600;}

  var reloj=document.getElementById('reloj'),
      nombreLuz=document.getElementById('nombre-luz'),
      lectura=document.getElementById('lectura'),
      deslizador=document.getElementById('hora'),
      volver=document.getElementById('volver');
  var elegida=false, actual={ink:[232,230,223], ac:[127,176,201], bg:[10,12,20]};

  deslizador.style.setProperty('--cielo','');
  root.style.setProperty('--cielo','linear-gradient(90deg,'+paradas.map(function(p){
    return rgb(p.bg)+' '+(p.h/24*100).toFixed(1)+'%';
  }).join(',')+')');

  function aplicar(h){
    var p=paleta(h);
    actual=p;
    root.style.setProperty('--bg',rgb(p.bg));
    root.style.setProperty('--ink',rgb(p.ink));
    root.style.setProperty('--accent',rgb(p.ac));
    root.style.setProperty('--dim',rgba(p.ink,.66));
    root.style.setProperty('--faint',rgba(p.ink,.42));
    root.style.setProperty('--line',rgba(p.ink,.17));
    root.style.setProperty('--panel',rgba(p.ink,.045));
    root.style.setProperty('--glow',rgba(p.ac,.16));
    root.style.colorScheme = (p.bg[0]*.299+p.bg[1]*.587+p.bg[2]*.114)<128 ? 'dark':'light';
    reloj.textContent=formato(h);
    nombreLuz.textContent=p.n;
    lectura.textContent=formato(h)+' · '+p.n+' · '+(elegida?'hora elegida':'tu hora');
    if(!elegida) deslizador.value=h;
    if(reducido) dibujar();
  }
  deslizador.addEventListener('input',function(){elegida=true;volver.hidden=false;aplicar(parseFloat(deslizador.value));});
  volver.addEventListener('click',function(){elegida=false;volver.hidden=true;aplicar(horaTuya());deslizador.focus();});
  aplicar(horaTuya());
  setInterval(function(){if(!elegida) aplicar(horaTuya());},20000);

  /* ---------- el campo de letras ---------- */
  var cv=document.getElementById('campo'), ctx=cv.getContext('2d');
  var FUENTE='ui-serif, Georgia, "Times New Roman", serif';
  var signos='abcdefghijklmnopqrstuvwxyzáéíóúñü¿?¡!,.;:—()'.split('');
  var letras=[], W=0, H=0, objetivo=110, px=-999, py=-999, activo=false;

  function azar(a,b){return a+Math.random()*(b-a);}
  function nueva(x,y,ch,calor){
    return {
      x:x, y:y, ch:ch||signos[(Math.random()*signos.length)|0],
      tam:azar(11,25), base:-azar(.04,.20), vx:azar(-.15,.15), vy:-azar(.04,.20),
      fase:azar(0,6.28), vaiven:azar(.04,.18), alfa:azar(.07,.19), calor:calor||0
    };
  }
  function poblar(){
    while(letras.length<objetivo) letras.push(nueva(azar(0,W),azar(0,H)));
    while(letras.length>objetivo+40){
      for(var i=0;i<letras.length;i++){ if(letras[i].calor<.05){letras.splice(i,1);break;} }
      if(letras.length>objetivo+80) letras.shift();
    }
  }
  function medir(){
    var dpr=Math.min(window.devicePixelRatio||1,2);
    W=window.innerWidth; H=window.innerHeight;
    cv.width=Math.round(W*dpr); cv.height=Math.round(H*dpr);
    cv.style.width=W+'px'; cv.style.height=H+'px';
    ctx.setTransform(dpr,0,0,dpr,0,0);
    objetivo=Math.max(45,Math.min(165,Math.round(W*H/11000)));
    poblar();
    if(reducido) dibujar();
  }

  function dibujar(){
    ctx.clearRect(0,0,W,H);
    var R=175, i, g;
    for(i=0;i<letras.length;i++){
      g=letras[i];
      var cerca=0;
      if(!reducido){
        g.vx*=.985; g.vy+=(g.base-g.vy)*.02;
        if(activo){
          var dx=px-g.x, dy=py-g.y, d=Math.sqrt(dx*dx+dy*dy);
          if(d<R && d>.5){
            var f=1-d/R, s=(d<52?-1.3:1)*f*.055;
            g.vx+=(dx/d)*s+(-dy/d)*f*.028;
            g.vy+=(dy/d)*s+( dx/d)*f*.028;
            cerca=f;
          }
        }
        var v=Math.sqrt(g.vx*g.vx+g.vy*g.vy);
        if(v>2.4){g.vx=g.vx/v*2.4;g.vy=g.vy/v*2.4;}
        g.fase+=.011;
        g.x+=g.vx+Math.sin(g.fase)*g.vaiven*.45;
        g.y+=g.vy;
        g.calor*=.9955;
        if(g.y<-40) {g.y=H+30; g.x=azar(0,W);}
        if(g.y>H+40){g.y=-30; g.x=azar(0,W);}
        if(g.x<-40) g.x=W+30;
        if(g.x>W+40) g.x=-30;
      }
      var col=mezcla(actual.ink,actual.ac,Math.min(1,g.calor));
      var a=Math.min(.85,g.alfa+g.calor*.55+cerca*.26);
      ctx.font=g.tam.toFixed(1)+'px '+FUENTE;
      ctx.fillStyle=rgba(col,a);
      ctx.fillText(g.ch,g.x,g.y);
    }
  }
  function bucle(){ if(!document.hidden) dibujar(); requestAnimationFrame(bucle); }

  window.addEventListener('resize',medir);
  window.addEventListener('pointermove',function(e){px=e.clientX;py=e.clientY;activo=true;},{passive:true});
  window.addEventListener('pointerleave',function(){activo=false;});
  window.addEventListener('blur',function(){activo=false;});
  medir();
  if(!reducido) requestAnimationFrame(bucle);

  /* ---------- soltar algo ---------- */
  var entrada=document.getElementById('soltar'),
      boton=document.getElementById('boton'),
      eco=document.getElementById('eco'),
      cuenta=0;
  var dichos=[
    'Se fue al fondo. No queda copia.',
    'Suelto: ahora es parte del ruido de letras.',
    'Listo. Ya no está en ningún lado, salvo en el dibujo.'
  ];
  function soltar(){
    var texto=entrada.value.trim();
    if(!texto){ eco.textContent='Escribí algo primero, aunque sea una letra.'; entrada.focus(); return; }
    var caja=entrada.getBoundingClientRect();
    var chars=texto.slice(0,70).split('');
    var utiles=chars.filter(function(c){return c.trim().length;});
    var paso=Math.min(26,caja.width/Math.max(1,utiles.length));
    var k=0;
    for(var i=0;i<chars.length;i++){
      if(!chars[i].trim()) continue;
      var g=nueva(caja.left+8+k*paso, caja.bottom-14, chars[i], 1);
      g.tam=azar(15,26);
      g.vx=azar(-1.1,1.1); g.vy=azar(-1.5,-.2); g.base=-azar(.05,.18);
      letras.push(g); k++;
    }
    if(reducido){
      dibujar();
      setTimeout(function(){ for(var j=0;j<letras.length;j++) letras[j].calor=0; dibujar(); },3500);
    }
    poblar();
    cuenta++;
    eco.innerHTML=dichos[(cuenta-1)%dichos.length]+' <span>· '+cuenta+(cuenta===1?' cosa soltada':' cosas soltadas')+'</span>';
    entrada.value='';
    entrada.focus();
  }
  boton.addEventListener('click',soltar);
  entrada.addEventListener('keydown',function(e){ if(e.key==='Enter'){e.preventDefault();soltar();} });
})();
</script>
</body>
</html>
